async function test() {
  const chromePath = '/home/zeph/.cache/ms-playwright/chromium-1248/chrome-linux64/chrome';
  const chrome = spawn(chromePath, [
    '--headless=new',
    '--remote-debugging-port=9222',
    '--disable-gpu',
    '--window-size=1000,320',
    '--hide-scrollbars',
    'http://localhost:3000/gif-record',
  ]);

  await new Promise((r) => setTimeout(r, 1500));

  try {
    const res = await fetch('http://127.0.0.1:9222/json/list');
    const tabs = await res.json();
    console.log('Tabs:', tabs.map((t) => ({ title: t.title, url: t.url, ws: t.webSocketDebuggerUrl })));
    const target = tabs.find((t) => t.url.includes('gif-record')) || tabs[0];
    if (!target) throw new Error('No target tab found');

    const ws = new WebSocket(target.webSocketDebuggerUrl);
    await new Promise((resolve) => (ws.onopen = resolve));
    console.log('Connected to CDP WebSocket');

    let msgId = 1;
    function send(method, params = {}) {
      return new Promise((resolve) => {
        const id = msgId++;
        const handler = (event) => {
          const data = JSON.parse(event.data);
          if (data.id === id) {
            ws.removeEventListener('message', handler);
            resolve(data.result);
          }
        };
        ws.addEventListener('message', handler);
        ws.send(JSON.stringify({ id, method, params }));
      });
    }

    await send('Page.enable');
    console.log('Page enabled');

    // Test screencast
    let frameCount = 0;
    const framesDir = '/tmp/test-frames';
    await mkdir(framesDir, { recursive: true });

    ws.onmessage = async (event) => {
      const msg = JSON.parse(event.data);
      if (msg.method === 'Page.screencastFrame') {
        const { data, sessionId } = msg.params;
        frameCount++;
        if (frameCount <= 5) {
          const buffer = Buffer.from(data, 'base64');
          await writeFile(join(framesDir, `frame_${String(frameCount).padStart(3, '0')}.png`), buffer);
          console.log(`Saved frame ${frameCount}`);
        }
        await send('Page.screencastFrameAck', { sessionId });
      }
    };

    console.log('Starting screencast...');
    await send('Page.startScreencast', {
      format: 'png',
      quality: 100,
      maxWidth: 1000,
      maxHeight: 320,
      everyNthFrame: 1,
    });

    await new Promise((r) => setTimeout(r, 2000));
    await send('Page.stopScreencast');
    console.log(`Total frames captured in 2s: ${frameCount}`);

    ws.close();
  } finally {
    chrome.kill();
  }
}

