import { spawn, execSync } from 'node:child_process';
import { mkdir, writeFile, rm } from 'node:fs/promises';
import { join } from 'node:path';
import { existsSync } from 'node:fs';

const FRAMES_DIR = '/tmp/treads-anim-frames';
const AMBIENT_FRAMES_DIR = '/tmp/treads-ambient-frames';
const CHROME_PATH = '/home/zeph/.cache/ms-playwright/chromium-1248/chrome-linux64/chrome';
const PORT = 9222;

async function sleep(ms) {
  return new Promise((r) => setTimeout(r, ms));
}

async function connectToChrome() {
  const res = await fetch(`http://127.0.0.1:${PORT}/json/list`);
  const tabs = await res.json();
  const target = tabs.find((t) => t.url.includes('gif-record')) || tabs[0];
  if (!target) throw new Error('No target tab found');

  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve) => (ws.onopen = resolve));

  let msgId = 1;
  function send(method, params = {}) {
    return new Promise((resolve) => {
      const id = msgId++;
      const handler = (event) => {
        const data = JSON.parse(event.data);
        if (data.id === id) {
          ws.removeEventListener('message', handler);
          resolve(data.result);
        }
      };
      ws.addEventListener('message', handler);
      ws.send(JSON.stringify({ id, method, params }));
    });
  }

  return { ws, send };
}

async function record() {
  console.log('Cleaning temp frames directory...');
  await rm(FRAMES_DIR, { recursive: true, force: true });
  await mkdir(FRAMES_DIR, { recursive: true });

  console.log('Launching headless Chrome...');
  const chrome = spawn(CHROME_PATH, [
    '--headless=new',
    `--remote-debugging-port=${PORT}`,
    '--disable-gpu',
    '--window-size=1000,300',
    '--hide-scrollbars',
    'http://localhost:3000/gif-record',
  ]);

  await sleep(2000);

  try {
    const { ws, send } = await connectToChrome();
    console.log('Connected to CDP');

    await send('Page.enable');
    await send('Emulation.setDeviceMetricsOverride', {
      width: 1000,
      height: 300,
      deviceScaleFactor: 1,
      mobile: false,
    });

    // Clean any overlays
    await send('Runtime.evaluate', {
      expression: `
        document.querySelectorAll('nextjs-portal, [class*="nextjs"], [class*="agentation"], button').forEach(el => el.remove());
        if (window.__resetAnimation) window.__resetAnimation();
      `,
    });

    await sleep(500);

    const frames = [];
    ws.onmessage = async (event) => {
      const msg = JSON.parse(event.data);
      if (msg.method === 'Page.screencastFrame') {
        const { data, sessionId, metadata } = msg.params;
        frames.push({ data, timestamp: metadata.timestamp });
        await send('Page.screencastFrameAck', { sessionId });
      }
    };

    console.log('Starting screencast...');
    await send('Page.startScreencast', {
      format: 'png',
      quality: 100,
      maxWidth: 1000,
      maxHeight: 300,
      everyNthFrame: 1,
    });

    console.log('Triggering animation...');
    await send('Runtime.evaluate', {
      expression: 'if (window.__startAnimation) window.__startAnimation();',
    });

    // Record for 6.2 seconds so vine draws (0-3.9s), flowers pop (0.5-4.2s), and settled bloom plays
    const RECORD_DURATION = 6200;
    console.log(`Recording for ${RECORD_DURATION}ms...`);
    await sleep(RECORD_DURATION);

    console.log('Stopping screencast...');
    await send('Page.stopScreencast');
    ws.close();

    console.log(`Captured ${frames.length} raw frames.`);
    if (frames.length === 0) {
      throw new Error('No frames captured!');
    }

    // Save frames with uniform indexing
    console.log('Saving frames to disk...');
    for (let i = 0; i < frames.length; i++) {
      const buf = Buffer.from(frames[i].data, 'base64');
      const filename = join(FRAMES_DIR, `frame_${String(i).padStart(5, '0')}.png`);
      await writeFile(filename, buf);
    }

    const calculatedFps = Math.round((frames.length / (RECORD_DURATION / 1000)));
    console.log(`Effective FPS: ~${calculatedFps}`);

    // Output directory
    const outputDir = join(process.cwd(), 'public');
    const mainGifPath = join(outputDir, 'treads-animation.gif');
    const crossfadeGifPath = join(outputDir, 'treads-loop.gif');

    console.log('Converting to high-quality looping GIF via ffmpeg...');
    // Generate palette and convert to GIF
    const ffmpegCmd = `ffmpeg -y -framerate ${calculatedFps} -i "${FRAMES_DIR}/frame_%05d.png" -filter_complex "[0:v] split [a][b];[a] palettegen=stats_mode=diff [p];[b][p] paletteuse=dither=bayer:bayer_scale=5:diff_mode=rectangle" -loop 0 "${mainGifPath}"`;
    execSync(ffmpegCmd, { stdio: 'inherit' });

    console.log(`Generated: ${mainGifPath}`);

    // Also generate crossfade looping version if desired
    // Crossfade the last 0.8s into the first 0.8s for seamless looping
    console.log('Generating seamless looping version (treads-loop.gif)...');
    const crossfadeCmd = `ffmpeg -y -framerate ${calculatedFps} -i "${FRAMES_DIR}/frame_%05d.png" -filter_complex "[0:v] split [main][pre];[main] trim=start=0:end=${(RECORD_DURATION / 1000) - 0.8},setpts=PTS-STARTPTS [body];[pre] trim=start=${(RECORD_DURATION / 1000) - 0.8}:end=${RECORD_DURATION / 1000},setpts=PTS-STARTPTS [fade_in];[body][fade_in] xfade=transition=fade:duration=0.8:offset=${(RECORD_DURATION / 1000) - 1.6} [merged];[merged] split [m1][m2];[m1] palettegen=stats_mode=diff [p];[m2][p] paletteuse=dither=bayer:bayer_scale=5:diff_mode=rectangle" -loop 0 "${crossfadeGifPath}"`;
    try {
      execSync(crossfadeCmd, { stdio: 'inherit' });
      console.log(`Generated: ${crossfadeGifPath}`);
    } catch (e) {
      console.warn('Crossfade variant skipped:', e.message);
    }

    console.log('Done!');
  } finally {
    chrome.kill();
  }
}

record().catch((err) => {
  console.error(err);
  process.exit(1);
});

