export default function GifRecordPage() {
  const [active, setActive] = React.useState(false);
  const [animKey, setAnimKey] = React.useState(0);

  React.useEffect(() => {
    try {
      localStorage.setItem('treads_consented', 'true');
    } catch {}

    const removeOverlays = () => {
      document.querySelectorAll('agentation-toolbar, [data-agentation-portal], nextjs-portal, nav, [role="dialog"]').forEach((el) => {
        el.remove();
      });
    };
    removeOverlays();
    const interval = setInterval(removeOverlays, 300);

    // Expose control to recording scripts
    (window as unknown as { __startAnimation: () => void }).__startAnimation = () => {
      removeOverlays();
      setActive(false);
      setTimeout(() => {
        setAnimKey((k) => k + 1);
        setActive(true);
      }, 50);
    };

    (window as unknown as { __resetAnimation: () => void }).__resetAnimation = () => {
      setActive(false);
      setAnimKey((k) => k + 1);
    };

    return () => clearInterval(interval);
  }, []);

  return (
    <div className="fixed inset-0 m-0 p-0 bg-foreground flex items-center justify-center overflow-hidden select-none">
      <style>{`
        body, html {
          margin: 0 !important;
          padding: 0 !important;
          overflow: hidden !important;
          background: #18201a !important;
        }
        nav, [role="dialog"], [data-radix-popper-content-wrapper],
        .agentation-root, [aria-label="Agentation"], nextjs-portal,
        agentation-toolbar, [data-agentation-portal],
        div[data-nextjs-toast], div[data-nextjs-dialog] {
          display: none !important;
          opacity: 0 !important;
          visibility: hidden !important;
          pointer-events: none !important;
        }
      `}</style>
      <div
        id="treads-record-box"
        className="relative w-[1000px] h-[300px] overflow-hidden"
        style={{ width: '1000px', height: '300px' }}
      >
        <TreadsFooter
          key={animKey}
          autoPlay={active}
          className="p-0 m-0 w-[1000px] h-[300px] bg-transparent"
        />
      </div>
    </div>
  );
}

import { spawn, execSync } from 'node:child_process';
import { mkdir, writeFile, rm } from 'node:fs/promises';
import { join } from 'node:path';

const FRAMES_DIR = '/tmp/treads-anim-frames';
const AMBIENT_FRAMES_DIR = '/tmp/treads-ambient-frames';
const CHROME_PATH = '/home/zeph/.cache/ms-playwright/chromium-1248/chrome-linux64/chrome';
const PORT = 9222;

async function sleep(ms) {
  return new Promise((r) => setTimeout(r, ms));
}

async function connectToChrome() {
  const res = await fetch(`http://127.0.0.1:${PORT}/json/list`);
  const tabs = await res.json();
  const target = tabs.find((t) => t.url.includes('gif-record')) || tabs[0];
  if (!target) throw new Error('No target tab found');

  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve) => (ws.onopen = resolve));

  let msgId = 1;
  function send(method, params = {}) {
    return new Promise((resolve) => {
      const id = msgId++;
      const handler = (event) => {
        const data = JSON.parse(event.data);
        if (data.id === id) {
          ws.removeEventListener('message', handler);
          resolve(data.result);
        }
      };
      ws.addEventListener('message', handler);
      ws.send(JSON.stringify({ id, method, params }));
    });
  }

  return { ws, send };
}

async function run() {
  console.log('1. Preparing directories...');
  await rm(FRAMES_DIR, { recursive: true, force: true });
  await mkdir(FRAMES_DIR, { recursive: true });

  console.log('2. Launching headless Chrome...');
  const chrome = spawn(CHROME_PATH, [
    '--headless=new',
    `--remote-debugging-port=${PORT}`,
    '--disable-gpu',
    '--window-size=1000,300',
    '--hide-scrollbars',
    'http://localhost:3000/gif-record',
  ]);

  await sleep(2500);

  try {
    const { ws, send } = await connectToChrome();
    console.log('Connected to CDP');

    await send('Page.enable');
    await send('Emulation.setDeviceMetricsOverride', {
      width: 1000,
      height: 300,
      deviceScaleFactor: 1,
      mobile: false,
    });

    // Strip any potential stray UI
    await send('Runtime.evaluate', {
      expression: `
        document.querySelectorAll('agentation-toolbar, [data-agentation-portal], nextjs-portal, nav, [role="dialog"], button').forEach(el => el.remove());
        if (window.__resetAnimation) window.__resetAnimation();
      `,
    });

    await sleep(600);

    // ==========================================
    // RECORD PHASE: Intro Animation (Growth & Bloom)
    // ==========================================
    console.log('3. Recording intro animation (vine growth & bloom)...');
    const introFrames = [];
    ws.onmessage = async (event) => {
      const msg = JSON.parse(event.data);
      if (msg.method === 'Page.screencastFrame') {
        const { data, sessionId, metadata } = msg.params;
        introFrames.push({ data, timestamp: metadata.timestamp });
        await send('Page.screencastFrameAck', { sessionId });
      }
    };

    await send('Page.startScreencast', {
      format: 'png',
      quality: 100,
      maxWidth: 1000,
      maxHeight: 300,
      everyNthFrame: 1,
    });

    await send('Runtime.evaluate', {
      expression: 'if (window.__startAnimation) window.__startAnimation();',
    });

    const RECORD_DURATION = 6000; // 6 seconds for complete bloom
    await sleep(RECORD_DURATION);

    await send('Page.stopScreencast');
    console.log(`Captured ${introFrames.length} intro frames.`);

    for (let i = 0; i < introFrames.length; i++) {
      const buf = Buffer.from(introFrames[i].data, 'base64');
      const filename = join(FRAMES_DIR, `frame_${String(i).padStart(5, '0')}.png`);
      await writeFile(filename, buf);
    }

    const calculatedFps = Math.round(introFrames.length / (RECORD_DURATION / 1000));
    console.log(`Calculated capture FPS: ${calculatedFps}`);

    const outputDir = join(process.cwd(), 'public');
    const mainGifPath = join(outputDir, 'treads.gif');
    const animGifPath = join(outputDir, 'treads-animation.gif');

    console.log('4. Encoding high quality looping GIF with ffmpeg...');
    // We downsample to 30fps for smooth web playback and optimal file size
    const cmd = `ffmpeg -y -framerate ${calculatedFps} -i "${FRAMES_DIR}/frame_%05d.png" -filter_complex "[0:v] fps=30,split [a][b];[a] palettegen=stats_mode=diff [p];[b][p] paletteuse=dither=bayer:bayer_scale=4:diff_mode=rectangle" -loop 0 "${mainGifPath}"`;
    execSync(cmd, { stdio: 'inherit' });

    execSync(`cp "${mainGifPath}" "${animGifPath}"`);
    console.log(`Saved primary GIF to: ${mainGifPath}`);
    console.log(`Saved duplicate GIF to: ${animGifPath}`);

    // Create a smooth crossfade version that loops seamlessly
    const loopGifPath = join(outputDir, 'treads-loop.gif');
    console.log('5. Encoding seamless crossfade loop version...');
    const totalSecs = (RECORD_DURATION / 1000).toFixed(1);
    const fadeDuration = 0.6;
    const bodyDuration = (totalSecs - fadeDuration).toFixed(1);
    const xfadeOffset = (bodyDuration - fadeDuration).toFixed(1);

    const xfadeCmd = `ffmpeg -y -framerate ${calculatedFps} -i "${FRAMES_DIR}/frame_%05d.png" -filter_complex "[0:v] fps=30,split [main][tail];[main] trim=start=0:end=${bodyDuration},setpts=PTS-STARTPTS [base];[tail] trim=start=${bodyDuration}:end=${totalSecs},setpts=PTS-STARTPTS [fadein];[base][fadein] xfade=transition=fade:duration=${fadeDuration}:offset=${xfadeOffset} [looped];[looped] split [c1][c2];[c1] palettegen=stats_mode=diff [p];[c2][p] paletteuse=dither=bayer:bayer_scale=4:diff_mode=rectangle" -loop 0 "${loopGifPath}"`;
    try {
      execSync(xfadeCmd, { stdio: 'inherit' });
      console.log(`Saved seamless loop GIF to: ${loopGifPath}`);
    } catch (e) {
      console.warn('Crossfade variant skipped:', e.message);
    }

    ws.close();
    console.log('All GIFs successfully generated!');
  } finally {
    chrome.kill();
  }
}

run().catch((err) => {
  console.error(err);
  process.exit(1);
});

