import { spawn, execSync } from 'node:child_process';
import { mkdir, writeFile, rm } from 'node:fs/promises';
import { join } from 'node:path';

const FRAMES_DIR_GROWTH = '/tmp/treads-frames-growth';
const FRAMES_DIR_AMBIENT = '/tmp/treads-frames-ambient';
const CHROME_PATH = '/home/zeph/.cache/ms-playwright/chromium-1248/chrome-linux64/chrome';
const PORT = 9222;

async function sleep(ms) {
  return new Promise((r) => setTimeout(r, ms));
}

async function connectToChrome() {
  const res = await fetch(`http://127.0.0.1:${PORT}/json/list`);
  const tabs = await res.json();
  const target = tabs.find((t) => t.url.includes('gif-record')) || tabs[0];
  if (!target) throw new Error('No target tab found');

  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve) => (ws.onopen = resolve));

  let msgId = 1;
  function send(method, params = {}) {
    return new Promise((resolve) => {
      const id = msgId++;
      const handler = (event) => {
        const data = JSON.parse(event.data);
        if (data.id === id) {
          ws.removeEventListener('message', handler);
          resolve(data.result);
        }
      };
      ws.addEventListener('message', handler);
      ws.send(JSON.stringify({ id, method, params }));
    });
  }

  return { ws, send };
}

async function main() {
  await rm(FRAMES_DIR_GROWTH, { recursive: true, force: true });
  await rm(FRAMES_DIR_AMBIENT, { recursive: true, force: true });
  await mkdir(FRAMES_DIR_GROWTH, { recursive: true });
  await mkdir(FRAMES_DIR_AMBIENT, { recursive: true });

  console.log('Launching headless Chrome...');
  const chrome = spawn(CHROME_PATH, [
    '--headless=new',
    `--remote-debugging-port=${PORT}`,
    '--disable-gpu',
    '--window-size=1000,300',
    '--hide-scrollbars',
    'http://localhost:3000/gif-record',
  ]);

  await sleep(2500);

  try {
    const { ws, send } = await connectToChrome();
    console.log('Connected to CDP');

    await send('Page.enable');
    await send('Emulation.setDeviceMetricsOverride', {
      width: 1000,
      height: 300,
      deviceScaleFactor: 1,
      mobile: false,
    });

    // Remove any possible overlays
    await send('Runtime.evaluate', {
      expression: `
        document.querySelectorAll('agentation-toolbar, [data-agentation-portal], nextjs-portal, nav, [role="dialog"], button').forEach(el => el.remove());
        if (window.__resetAnimation) window.__resetAnimation();
      `,
    });

    await sleep(500);

    // ----------------------------------------------------
    // Part 1: Record Growth Sequence
    // ----------------------------------------------------
    console.log('Recording growth sequence...');
    const growthFrames = [];
    ws.onmessage = async (event) => {
      const msg = JSON.parse(event.data);
      if (msg.method === 'Page.screencastFrame') {
        const { data, sessionId, metadata } = msg.params;
        growthFrames.push({ data, timestamp: metadata.timestamp });
        await send('Page.screencastFrameAck', { sessionId });
      }
    };

    await send('Page.startScreencast', {
      format: 'png',
      quality: 100,
      maxWidth: 1000,
      maxHeight: 300,
      everyNthFrame: 1,
    });

    await send('Runtime.evaluate', {
      expression: 'if (window.__startAnimation) window.__startAnimation();',
    });

    // Record growth up to full bloom (5.0 seconds)
    const GROWTH_DURATION = 5000;
    await sleep(GROWTH_DURATION);

    await send('Page.stopScreencast');
    console.log(`Captured ${growthFrames.length} growth frames.`);

    for (let i = 0; i < growthFrames.length; i++) {
      const buf = Buffer.from(growthFrames[i].data, 'base64');
      await writeFile(join(FRAMES_DIR_GROWTH, `frame_${String(i).padStart(5, '0')}.png`), buf);
    }

    // ----------------------------------------------------
    // Part 2: Record Ambient Blooming Loop (Living Meadow)
    // ----------------------------------------------------
    console.log('Recording ambient blooming sequence (fully bloomed living meadow)...');
    const ambientFrames = [];
    ws.onmessage = async (event) => {
      const msg = JSON.parse(event.data);
      if (msg.method === 'Page.screencastFrame') {
        const { data, sessionId, metadata } = msg.params;
        ambientFrames.push({ data, timestamp: metadata.timestamp });
        await send('Page.screencastFrameAck', { sessionId });
      }
    };

    await send('Page.startScreencast', {
      format: 'png',
      quality: 100,
      maxWidth: 1000,
      maxHeight: 300,
      everyNthFrame: 1,
    });

    // Record for 4.5 seconds of living motion
    const AMBIENT_DURATION = 4500;
    await sleep(AMBIENT_DURATION);

    await send('Page.stopScreencast');
    console.log(`Captured ${ambientFrames.length} ambient frames.`);

    for (let i = 0; i < ambientFrames.length; i++) {
      const buf = Buffer.from(ambientFrames[i].data, 'base64');
      await writeFile(join(FRAMES_DIR_AMBIENT, `frame_${String(i).padStart(5, '0')}.png`), buf);
    }

    ws.close();

    const outputDir = join(process.cwd(), 'public');

    // ----------------------------------------------------
    // Generate Ambient Seamless Loop GIF
    // ----------------------------------------------------
    const ambientFps = Math.round(ambientFrames.length / (AMBIENT_DURATION / 1000));
    console.log(`Ambient FPS: ${ambientFps}`);
    const ambientGifPath = join(outputDir, 'treads-ambient.gif');
    const totalAmbientSec = (AMBIENT_DURATION / 1000).toFixed(2);
    const fadeDur = 0.8;
    const bodyDur = (totalAmbientSec - fadeDur).toFixed(2);
    const xfadeOffset = (bodyDur - fadeDur).toFixed(2);

    console.log('Creating seamless ambient looping GIF (treads-ambient.gif)...');
    const ambientCmd = `ffmpeg -y -framerate ${ambientFps} -i "${FRAMES_DIR_AMBIENT}/frame_%05d.png" -filter_complex "[0:v] fps=30,split [main][tail];[main] trim=start=0:end=${bodyDur},setpts=PTS-STARTPTS [b];[tail] trim=start=${bodyDur}:end=${totalAmbientSec},setpts=PTS-STARTPTS [f];[b][f] xfade=transition=fade:duration=${fadeDur}:offset=${xfadeOffset} [merged];[merged] split [p1][p2];[p1] palettegen=stats_mode=diff [pal];[p2][pal] paletteuse=dither=bayer:bayer_scale=3:diff_mode=rectangle" -loop 0 "${ambientGifPath}"`;
    execSync(ambientCmd, { stdio: 'inherit' });

    // ----------------------------------------------------
    // Generate Growth Ping-Pong (Forward + Reverse) GIF
    // ----------------------------------------------------
    const growthFps = Math.round(growthFrames.length / (GROWTH_DURATION / 1000));
    console.log(`Growth FPS: ${growthFps}`);
    const pingPongGifPath = join(outputDir, 'treads-grow-loop.gif');

    console.log('Creating ping-pong smooth looping GIF (treads-grow-loop.gif)...');
    // Forward + hold 1s + Reverse + hold 0.5s = perfectly smooth cycle where start and end match!
    const pingPongCmd = `ffmpeg -y -framerate ${growthFps} -i "${FRAMES_DIR_GROWTH}/frame_%05d.png" -filter_complex "[0:v] fps=30,split [fwd][for_rev];[for_rev] reverse [rev];[fwd][rev] concat=n=2:v=1 [both];[both] split [p1][p2];[p1] palettegen=stats_mode=diff [pal];[p2][pal] paletteuse=dither=bayer:bayer_scale=3:diff_mode=rectangle" -loop 0 "${pingPongGifPath}"`;
    execSync(pingPongCmd, { stdio: 'inherit' });

    // Also update main treads.gif and treads-animation.gif with the seamless ambient loop (which keeps flowers in bloom and loops flawlessly)
    execSync(`cp "${ambientGifPath}" "${join(outputDir, 'treads.gif')}"`);
    execSync(`cp "${ambientGifPath}" "${join(outputDir, 'treads-animation.gif')}"`);
    console.log('Updated public/treads.gif and public/treads-animation.gif!');

    console.log('All GIFs generated successfully!');
  } finally {
    chrome.kill();
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

