      commonName: z.string(),
      kind: z.string(),
      confidence: z.enum(['Likely', 'Possible', 'Unsure']),
      wikipediaTitle: z.string(),
    })
  ),
});

const fixtures = JSON.parse(fs.readFileSync('public/eval-fixtures/fixtures.json', 'utf8'));
const model = google('gemma-4-26b-a4b-it');

async function testOne(fixture) {
  const startTime = Date.now();
  try {
    const { object } = await generateObject({
      model,
      schema: IdentificationResponseSchema,
      prompt: 'Naturalist identification query: \"' + fixture.description + '\". Name: \"' + fixture.name + '\". Category: \"' + fixture.category + '\". If this is a non-organism (inanimate object) or a human person, mark isLivingOrganism as false and refuse identification honestly. Otherwise, provide up to 3 candidate species with scientific and common names.'
    });
    const latencyMs = Date.now() - startTime;
    let passed = false;
    if (fixture.expectRefusal) {
      passed = !object.isLivingOrganism;
    } else {
      const targetSci = (fixture.expectedScientificName || '').toLowerCase();
      const targetCommon = fixture.expectedCommonName.toLowerCase();
      passed = object.isLivingOrganism && object.candidates.slice(0, 3).some((c) => {
        const cSci = c.scientificName.toLowerCase();
        const cCommon = c.commonName.toLowerCase();
        return (targetSci && (cSci.includes(targetSci) || targetSci.includes(cSci))) || cCommon.includes(targetCommon) || targetCommon.includes(cCommon);
      });
    }
    return { passed, latencyMs, error: null, isLiving: object.isLivingOrganism };
  } catch (e) {
    return { passed: false, latencyMs: Date.now() - startTime, error: e.message, isLiving: null };
  }
}

async function run() {
  console.log('Running all 30 fixtures with LIVE Gemma 4...');
  let organismPassed = 0, refusalPassed = 0, parseErrors = 0, totalLatency = 0;
  for (const f of fixtures) {
    const res = await testOne(f);
    totalLatency += res.latencyMs;
    if (res.error) {
      parseErrors++;
      console.log('✗', f.id, f.expectRefusal ? '[REFUSAL]' : '[ORGANISM]', f.name, '(' + res.latencyMs + 'ms) - PARSE ERROR');
    } else {
      if (f.expectRefusal && res.passed) refusalPassed++;
      if (!f.expectRefusal && res.passed) organismPassed++;
      console.log((res.passed ? '✓' : '✗'), f.id, f.expectRefusal ? '[REFUSAL]' : '[ORGANISM]', f.name, '(' + res.latencyMs + 'ms)');
    }
  }
  console.log('\n--- LIVE GEMMA 4 RESULTS ---');
  console.log('Organisms correct:', organismPassed, '/ 20 (' + ((organismPassed/20)*100).toFixed(1) + '%)');
  console.log('Refusals correct:', refusalPassed, '/ 10 (' + ((refusalPassed/10)*100).toFixed(1) + '%)');
  console.log('Parse errors:', parseErrors, '/ 30');
  console.log('Average latency:', Math.round(totalLatency/30), 'ms');
}
run();
